[BITS 16]\norg 0x7C00\n\n; Bootloader entry point\nstart:\n    cli                         ; Disable interrupts\n    xor ax, ax\n    mov ds, ax\n    mov es, ax\n    mov ss, ax\n    mov sp, 0x7C00              ; Set stack pointer\n    \n    ; Print bootloader message\n    mov si, boot_msg\n    call print_string\n    \n    ; Enable A20 line\n    call enable_a20\n    \n    ; Print A20 enabled message\n    mov si, a20_msg\n    call print_string\n    \n    ; Load GDT\n    lgdt [gdt_descriptor]\n    \n    ; Print GDT loaded message\n    mov si, gdt_msg\n    call print_string\n    \n    ; Set PE (Protection Enable) bit in CR0\n    mov eax, cr0\n    or eax, 1\n    mov cr0, eax\n    \n    ; Far jump to 32-bit code\n    jmp 0x08:protected_mode\n\n; Print string subroutine\nprint_string:\n    .loop:\n        lodsb\n        cmp al, 0\n        je .done\n        mov ah, 0x0E\n        int 0x10\n        jmp .loop\n    .done:\n        ret\n\n; Enable A20 line\nenable_a20:\n    in al, 0x92\n    or al, 2\n    out 0x92, al\n    ret\n\n; Boot messages\nboot_msg db 'Toriganal OS Bootloader v1.0', 13, 10, 0\na20_msg db 'A20 Line Enabled', 13, 10, 0\ngdt_msg db 'GDT Loaded - Entering Protected Mode...', 13, 10, 0\n\n; GDT Table\ngdt_start:\n    ; Null descriptor\n    dq 0x0\n    \n    ; Code descriptor (Ring 0)\n    dw 0xFFFF           ; Limit\n    dw 0x0000           ; Base (low)\n    db 0x00             ; Base (mid)\n    db 10011010b        ; Access byte: Present, Ring 0, Code, Readable\n    db 11001111b        ; Granularity: 4KB granularity, 32-bit\n    db 0x00             ; Base (high)\n    \n    ; Data descriptor (Ring 0)\n    dw 0xFFFF           ; Limit\n    dw 0x0000           ; Base (low)\n    db 0x00             ; Base (mid)\n    db 10010010b        ; Access byte: Present, Ring 0, Data, Writable\n    db 11001111b        ; Granularity: 4KB granularity, 32-bit\n    db 0x00             ; Base (high)\n\ngdt_end:\n\ngdt_descriptor:\n    dw gdt_end - gdt_start - 1\n    dd gdt_start\n\n[BITS 32]\nprotected_mode:\n    ; Set data segment registers\n    mov ax, 0x10\n    mov ds, ax\n    mov es, ax\n    mov ss, ax\n    mov fs, ax\n    mov gs, ax\n    \n    ; Set up stack\n    mov esp, 0x90000\n    \n    ; Clear screen and print protected mode message\n    call clear_screen\n    \n    mov esi, protected_msg\n    call print_string_pm\n    \n    ; Call kernel main\n    call kernel_main\n    \n    ; Halt\n    cli\n    hlt\n\n; Clear VGA screen in protected mode\nclear_screen:\n    mov edi, 0xB8000\n    mov ecx, 80 * 25\n    mov ax, 0x0720  ; Space character with black background, white foreground\n    rep stosw\n    ret\n\n; Print string in protected mode\nprint_string_pm:\n    mov edi, 0xB8000\n    mov ah, 0x0A  ; Green on black\n.loop_pm:\n    lodsb\n    cmp al, 0\n    je .done_pm\n    stosw\n    jmp .loop_pm\n.done_pm:\n    ret\n\nprotected_msg db 'Protected Mode Activated!', 0\n\nextern kernel_main\n\n; Boot signature\ntimes 510-($-$$) db 0\ndw 0xAA55